import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { Link as RouteLink } from 'react-router-dom';

const ZIMM_COLOUR_SWATCH_RECIPE = 'ZimmColourSwatch';

// Same import base SFCC's own swatch-group/swatch.jsx uses for its `RouteLink` — a router
// `Link` is what actually delivers "URL updates without a full page reload": it pushes history
// rather than navigating the document. There is no overrides/.../link equivalent to reuse
// instead — confirmed none exists for this.
const ColourSwatchLink = chakra(RouteLink);

type ZimmColourSwatchProps = {
  /** Colour display name. Not rendered as visible text — used as the accessible name (`aria-label`). */
  name: string;
  /**
   * Fully resolved image URL for this colour's swatch fill. Resolution is the caller's job —
   * this component performs no SFCC-shape lookup of its own.
   */
  imageUrl: string;
  /**
   * Destination URL for this colour variation. Absent for the quick-view-modal path, where
   * SFCC's own `useVariationAttributes` returns `href: null` and the swatch must not navigate.
   */
  href?: string;
  /** Whether this is the currently selected colour. */
  isSelected: boolean;
  /**
   * Whether this swatch is reachable via Tab (`tabIndex={0}`) vs. removed from the tab order
   * (`tabIndex={-1}`) — the caller drives a roving tabindex across the swatch group.
   */
  isFocusable: boolean;
};

/**
 * Atom — a single colour swatch in a PDP colour-variation list: a clickable rectangle filled
 * with that colour's product photo, radio semantics (one selection out of the group), and a
 * router `Link` when a destination URL exists so selecting a colour updates the URL without a
 * full page reload.
 *
 * Purely presentational — no data-fetching hook of any kind. SFCC data resolution (building
 * `imageUrl`/`href` from a product's variation attributes) happens at the page level, not this
 * atom.
 */
export const ZimmColourSwatch = ({ name, imageUrl, href, isSelected, isFocusable }: ZimmColourSwatchProps) => {
  // Above any early return — there isn't one here, this component always renders something.
  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_RECIPE, { selected: isSelected });

  // The dynamic URL genuinely cannot live in the static recipe file, so this one dynamic `__css`
  // spread is the correct, deliberate exception — the same shape already used at
  // footer/footerNavColumn/index.tsx:44 and :62, an established pattern in this codebase.
  const image = <chakra.span __css={{ ...styles.image, backgroundImage: `url(${imageUrl})` }} />;

  /*
   * Deliberately no `backgroundColor={name.toLowerCase()}` here, unlike base SFCC's own
   * `renderDefaultVariationAttribute` (product-view/index.jsx, and our own extraction of it in
   * product-view/index.tsx). Three reasons this stays out, permanently, not an oversight to
   * "fix" back in later:
   *   1. It uses the colour's display name as a raw CSS colour keyword — "Ivory" resolves as a
   *      real CSS colour, "Bay Blue" does not — which is both unauditable by `audit:tokens` and
   *      against this codebase's no-raw-design-value rule.
   *   2. In base it exists to tint the swatch behind a *missing* product image. This component is
   *      only ever rendered for colour variations that already have a populated image — the
   *      caller filters out any variation without one before rendering this component at all —
   *      so there is never a missing image for a fallback tint to show behind.
   *   3. Even if one slipped through, `background-size: cover` on the image (see the recipe's
   *      `image` part) would hide any tint sitting behind it regardless.
   */
  if (href) {
    return (
      <ColourSwatchLink
        to={href}
        __css={styles.swatch}
        role="radio"
        aria-checked={isSelected}
        aria-label={name}
        tabIndex={isFocusable ? 0 : -1}
        data-testid="colour-swatch"
      >
        {image}
      </ColourSwatchLink>
    );
  }

  return (
    <chakra.span
      __css={styles.swatch}
      role="radio"
      aria-checked={isSelected}
      aria-label={name}
      tabIndex={isFocusable ? 0 : -1}
      data-testid="colour-swatch"
    >
      {image}
    </chakra.span>
  );
};

